content:
{
  "is_open_solicitation": true,
  "buyer": "Achievement First",
  "title": "Request for Proposals: Website Redesign & Ecosystem Development",
  "due_date": "2026-11-02",
  "fit_score": 30,
  "why_fit": [
    "Massachusetts-based digital agency with hand-coded, mobile-first websites",
    "Experience with WordPress hosting, maintenance, daily backups, SSL",
    "Structured data and SEO/AEO focus aligns with RFP's technical SEO requirements",
    "Flutter app development shows modern engineering capability",
    "Local SEO and Google Business Profile experience relevant for school directories"
  ],
  "gaps": [
    "No demonstrated experience with 41-site multi-tier enterprise CMS implementations",
    "No case studies of federated/multi-site governance models",
    "No non-profit or K-12 education sector references",
    "No documented WCAG 2.2 AA accessibility compliance track record",
    "No multilingual (English/Spanish) architecture experience",
    "No integrations with SchoolMint, HubSpot, Greenhouse, Salesforce, Fundraise Up, Okta",
    "Insurance coverage (General Liability, Cyber Liability, E&O) not confirmed",
    "Team size and in-house UX/accessibility/engineering depth unproven at this scale",
    "No Figma design system handoff or component library methodology shown",
    "Content migration at 41-site scale with governance workflows not evidenced",
    "Security protocols (SSO/MFA/SCIM, RPO/RTO backup specs) not demonstrated"
  ],
  "requirements": [
    "Proposal in PDF format via email",
    "Submit to Jacqui Alessi (Associate Chief of Marketing & Communications)",
    "Deadline: November 2, 2026",
    "Organize strictly in 7 sections: Executive Summary, Agency Profile & Team, Case Studies & References, Technical Solution, Work Plan & Schedule, Pricing & TCO, Terms & Compliance",
    "Proposals valid for 90 days post-submission",
    "Vendor questions due by October 15, 2026 (per Appendix timeline) or October 19, 2026 (per RFP Key Milestones)",
    "Three case studies with multi-site implementations, live URLs, client references",
    "Explicit scope assumptions per Appendix B checklist",
    "Insurance verification (General Liability, Cyber Liability, Errors & Omissions)",
    "IP ownership confirmation and contract exceptions"
  ],
  "evidence": [
    {
      "claim": "Buyer is a non-profit charter network with 41 schools across three states",
      "quote": "Achievement First (AF) is a non-profit charter school network serving more than 15,000 students across 41 schools in Connecticut, New York, and Rhode Island."
    },
    {
      "claim": "RFP seeks unified ecosystem with network, regional, and 41 school tiers",
      "quote": "The solution will comprise a main network website, regional hubs, and 41 distinct school-specific websites under a central governance model."
    },
    {
      "claim": "Proposal deadline is November 2, 2026 via email in PDF",
      "quote": "Proposals must be submitted in PDF format via email no later than November 2, 2026 to: Jacqui Alessi Associate Chief of Marketing & Communications"
    },
    {
      "claim": "Three multi-site case studies with live URLs required",
      "quote": "Three relevant case studies (including multi-site implementations) with measurable outcomes, live URLs, and client references."
    },
    {
      "claim": "Non-profit or public K-12 experience required",
      "quote": "Experience working with non-profits, public K-12 education, or public sector clients."
    },
    {
      "claim": "Insurance must include General Liability, Cyber Liability, E&O",
      "quote": "Adequate insurance coverage (General Liability, Cyber Liability, Errors & Omissions)."
    },
    {
      "claim": "WCAG 2.2 AA compliance with manual testing required",
      "quote": "WCAG 2.2 AA Compliance: Full adherence to WCAG 2.2 Level AA standards verified via automated tools and manual screen-reader/keyboard testing."
    },
    {
      "claim": "Multilingual English/Spanish architecture required",
      "quote": "Multilingual Architecture: Seamless multi-language framework supporting human translations, intuitive language selectors, and localized metadata."
    },
    {
      "claim": "CMS must be enterprise-grade: WordPress Multisite, Drupal, or headless",
      "quote": "CMS Selection: Recommend a modern, secure CMS (e.g., Enterprise WordPress, WordPress Multisite, Drupal, or Headless solution) suitable for non-profit scale."
    },
    {
      "claim": "Security requires SSO/MFA/SCIM and strict backup RPO/RTO",
      "quote": "Security Protocols: Role-based access controls, SSO/MFA/SCIM capability, SSL, automated backups... minimum requirements include daily automated backups across all 41 school sites plus network and regional tiers, 30-day retention minimum, Recovery Point Objective [RPO] of 24 hours or less, and Recovery Time Objective [RTO] of 8 hours or less for full platform restore"
    },
    {
      "claim": "Full IP ownership transfer to AF required",
      "quote": "Full Ownership: AF retains 100% ownership of code repositories, design assets, content, data, domain registrations, and credentials."
    },
    {
      "claim": "Vendor must avoid proprietary lock-in and disclose all fees",
      "quote": "Vendor Independence: Avoid proprietary lock-in; transparently disclose all licensing fees, external plugins, and SaaS dependencies."
    }
  ]
}
